import numpy as np
np.set_printoptions(precision=2, suppress=True, linewidth=220)
H=6; hd=64
def Wqh(l,h): s=slice(h*hd,(h+1)*hd); return W[f'W_q.{l}'][s]*W[f'ln1_w.{l}'][None,:]
def Wkh(l,h): s=slice(h*hd,(h+1)*hd); return W[f'W_k.{l}'][s]*W[f'ln1_w.{l}'][None,:]
def Wvh(l,h): s=slice(h*hd,(h+1)*hd); return W[f'W_v.{l}'][s]*W[f'ln1_w.{l}'][None,:]
def Woh(l,h): s=slice(h*hd,(h+1)*hd); return W[f'W_o.{l}'][:,s]
def OV(l,h): return Woh(l,h)@Wvh(l,h)
def comp(Mread, OVw):
    return np.linalg.norm(Mread@OVw)/(np.linalg.norm(Mread)*np.linalg.norm(OVw))
rng=np.random.default_rng(0)
# baseline: random matrices
base=[]
for t in range(20):
    A=rng.normal(size=(64,384)); B=rng.normal(size=(384,64))@rng.normal(size=(64,384))
    base.append(comp(A,B))
print("random baseline", np.mean(base))
for kind,f in [('Q',Wqh),('K',Wkh),('V',Wvh)]:
    print("==",kind,"composition: rows = writer (layer l1 head), cols = reader heads")
    for l1 in range(3):
        for h1 in range(H):
            O=OV(l1,h1)
            row=[]
            for l2 in range(l1+1,4):
                row.append([comp(f(l2,h2),O) for h2 in range(H)])
            print(f"L{l1}H{h1}", " | ".join(" ".join(f"{v:.2f}" for v in r) for r in row))
